import re

def from_roman(s):
    """Convert a Roman numeral string to an integer.

    Accepts only standard form from 1 to 3999.
    Raises ValueError for any invalid input.
    """
    if not isinstance(s, str) or not s:
        raise ValueError("Invalid Roman numeral")

    # Check uppercase only
    if not s.isupper():
        raise ValueError("Invalid Roman numeral")

    # Define valid patterns for each place
    # Thousands: M{0,3} but at least one digit overall
    # Hundreds: (CM|CD|D?C{0,3})
    # Tens: (XC|XL|L?X{0,3})
    # Units: (IX|IV|V?I{0,3})

    # Full regex for valid Roman numerals 1-3999
    pattern = r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$'

    if not re.match(pattern, s):
        raise ValueError("Invalid Roman numeral")

    # Now convert
    # Parse thousands
    i = 0
    thousands = 0
    while i < len(s) and s[i] == 'M':
        thousands += 1000
        i += 1

    # Parse hundreds
    hundreds = 0
    if i < len(s):
        if s[i] == 'C':
            if i + 1 < len(s) and s[i+1] == 'M':
                hundreds = 900
                i += 2
            elif i + 1 < len(s) and s[i+1] == 'D':
                hundreds = 400
                i += 2
            else:
                # C, CC, CCC
                while i < len(s) and s[i] == 'C':
                    hundreds += 100
                    i += 1
        elif s[i] == 'D':
            hundreds = 500
            i += 1
            while i < len(s) and s[i] == 'C':
                hundreds += 100
                i += 1

    # Parse tens
    tens = 0
    if i < len(s):
        if s[i] == 'X':
            if i + 1 < len(s) and s[i+1] == 'C':
                tens = 90
                i += 2
            elif i + 1 < len(s) and s[i+1] == 'L':
                tens = 40
                i += 2
            else:
                # X, XX, XXX
                while i < len(s) and s[i] == 'X':
                    tens += 10
                    i += 1
        elif s[i] == 'L':
            tens = 50
            i += 1
            while i < len(s) and s[i] == 'X':
                tens += 10
                i += 1

    # Parse units
    units = 0
    if i < len(s):
        if s[i] == 'I':
            if i + 1 < len(s) and s[i+1] == 'X':
                units = 9
                i += 2
            elif i + 1 < len(s) and s[i+1] == 'V':
                units = 4
                i += 2
            else:
                # I, II, III
                while i < len(s) and s[i] == 'I':
                    units += 1
                    i += 1
        elif s[i] == 'V':
            units = 5
            i += 1
            while i < len(s) and s[i] == 'I':
                units += 1
                i += 1

    if i != len(s):
        raise ValueError("Invalid Roman numeral")

    result = thousands + hundreds + tens + units
    if result < 1 or result > 3999:
        raise ValueError("Invalid Roman numeral")

    return result


# Test the examples
test_cases = [
    ("III", 3),
    ("IV", 4),
    ("IX", 9),
    ("LVIII", 58),
    ("MCMXCIV", 1994),
]

print("Testing valid cases:")
for roman, expected in test_cases:
    result = from_roman(roman)
    status = "PASS" if result == expected else "FAIL"
    print(f"  {roman} -> {result} (expected {expected}) [{status}]")

# Test invalid cases
invalid_cases = ["IIII", "IC", "", "iiii", "iv", "MCMXCIVI", "MMMM", "VX", "LC", "DM"]

print("\nTesting invalid cases (should raise ValueError):")
for roman in invalid_cases:
    try:
        result = from_roman(roman)
        print(f"  {roman!r} -> {result} [FAIL - should have raised ValueError]")
    except ValueError:
        print(f"  {roman!r} -> ValueError [PASS]")
    except Exception as e:
        print(f"  {roman!r} -> {type(e).__name__}: {e} [FAIL - wrong exception]")

